def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def read_verified_bytes(path: str, expected_sha256: str, label: str,
                        expected_size: int | None = None) -> tuple[bytes, dict]:
    """Read an authorized immutable file and verify its declared digest/size."""
    if not os.path.isfile(path):
        raise BindingError(f"{label}: authorized file absent at {path}")
