def decode_envelope_rows(manifest: dict, part_evidence: list) -> list[dict]:
    """Decode transport parquet parts into logical dicts via columns[] + presence.

    The manifest columns[] map describes ONLY this manifest's own parts. Each
    logical field is read by its storageName; the paired pN Boolean is a
    presence flag and is never treated as record content. A null cN whose pN is
    true is an explicit null. JSON cells alone are decoded with
    json.loads(parse_float=Decimal); STRING cells are already text.
    """
    try:
        import pyarrow.parquet as pq
    except ImportError as exc:  # pragma: no cover - dependency is in the snapshot
        raise ParseError(f"pyarrow unavailable in the sandbox: {exc}") from exc

    columns = manifest["columns"]
    storage_names = {col["storageName"] for col in columns}
    logical_rows: list[dict] = []
    declared_part_rows = 0

    for part in manifest["parts"]:
        path = f"{DATA_ROOT}/{part['fileId']}/{part['fileName']}"
        _, evidence = read_verified_bytes(
            path, part["sha256"], f"transport part {part['fileName']}",
            expected_size=part.get("sizeBytes"),
        )
        evidence["declaredRowCount"] = part["rowCount"]
        part_evidence.append(evidence)
        declared_part_rows += int(part["rowCount"])

        table = pq.read_table(path)
        physical_rows = table.to_pylist()
        if len(physical_rows) != int(part["rowCount"]):
            raise BindingError(
                f"{part['fileName']}: row count declared={part['rowCount']} "
                f"actual={len(physical_rows)}"
            )

        for physical in physical_rows:
            # Presence flags must exist for every mapped data column.
            missing_flags = [
                key for key in storage_names if ("p" + key[1:]) not in physical
            ]
            if missing_flags:
                raise BindingError(
                    f"{part['fileName']}: presence columns absent for {missing_flags}"
                )
            logical: dict = {}
            for col in columns:
                key = col["storageName"]
                presence = physical["p" + key[1:]]
                if presence is False:
                    continue  # field omitted: not present in this record
                raw = physical[key]
                if raw is None:
                    logical[col["name"]] = None  # explicit null
                    continue
                if col["type"] == "JSON":
                    if isinstance(raw, (bytes, bytearray)):
                        raw = raw.decode("utf-8")
                    if isinstance(raw, str):
                        logical[col["name"]] = json.loads(
                            raw, parse_float=Decimal, parse_int=Decimal
                        )
                    else:
                        logical[col["name"]] = raw
                elif col["type"] == "DECIMAL":
                    logical[col["name"]] = Decimal(str(raw))
                else:
                    logical[col["name"]] = raw if isinstance(raw, str) else str(raw)
            logical_rows.append(logical)

    if len(logical_rows) != int(manifest["rowCount"]):
        raise BindingError(
            f"manifest rowCount declared={manifest['rowCount']} "
            f"decoded={len(logical_rows)}"
        )
    if declared_part_rows != int(manifest["rowCount"]):
        raise BindingError(
            f"sum of part rowCount={declared_part_rows} disagrees with manifest "
            f"rowCount={manifest['rowCount']}"
        )
    return logical_rows

