def select_single_native_file(manifest: dict) -> dict:
    """Select the ONE authorized original CSV from manifest nativeFiles."""
    natives = manifest.get("nativeFiles") or []
    if len(natives) != 1:
        raise BindingError(
            f"expected exactly one nativeFiles entry for a single-CSV objective, "
            f"got {len(natives)}"
        )
    native = natives[0]
    if native.get("fileId") != NATIVE_FILE_ID or native.get("fileName") != NATIVE_FILE_NAME:
        raise BindingError(
            "nativeFiles entry identity differs from the authorized descriptor: "
            f"{native.get('fileId')}/{native.get('fileName')}"
        )
    if native.get("format") != "CSV":
        raise BindingError(f"declared native format is not CSV: {native.get('format')!r}")
    if native.get("sha256") != EXPECTED_NATIVE_SHA256:
        raise BindingError("nativeFiles declared digest differs from the descriptor digest")
    if int(native.get("sizeBytes", -1)) != EXPECTED_NATIVE_SIZE:
        raise BindingError("nativeFiles declared size differs from the descriptor size")
    return native


def crosscheck_envelope_record(logical_rows: list[dict], native: dict,
                               actual_sha256: str, actual_size: int) -> dict:
    """Bind the envelope chunk metadata to the verified original bytes.

    The envelope record is transport metadata about the original file (role
    SOURCE_FILE, contentDelivery IMMUTABLE_INPUT_FILE_ONLY). It is used here
    only to prove WHICH single original was selected and that its declared
    chunk integrity metadata matches the verified bytes. Its numeric fields are
    Decimal because JSON cells are decoded with parse_float/parse_int=Decimal.
    """
    if len(logical_rows) != 1:
        raise BindingError(f"expected 1 envelope logical row, got {len(logical_rows)}")
    row = logical_rows[0]
    if set(row) != {"datasetReference", "record"}:
        raise BindingError(
            f"envelope logical fields unexpected: {sorted(row)}"
        )
    if row["datasetReference"] != CSV_DATASET_REFERENCE:
        raise BindingError(
            "envelope datasetReference is not the exact delivered CSV asset key: "
            f"{row['datasetReference']!r}"
        )
    record = row["record"]
    if not isinstance(record, dict):
        raise BindingError(f"envelope record is not a JSON object: {type(record).__name__}")

    checks: list[dict] = []

    def check(field: str, declared, observed, note: str) -> None:
        ok = declared == observed
        checks.append({
            "field": field,
            "declaredInEnvelope": str(declared),
            "observedFromVerifiedBytes": str(observed),
            "match": ok,
            "note": note,
        })
        if not ok:
            raise BindingError(
                f"envelope field {field} declared={declared!r} observed={observed!r}"
            )

    check("fileName", record.get("fileName"), native.get("originalName"),
          "envelope fileName equals manifest nativeFiles originalName")
    check("sha256", record.get("sha256"), actual_sha256,
          "envelope declared digest equals the recomputed digest of the bytes read")
    check("chunkSha256", record.get("chunkSha256"), actual_sha256,
          "single-chunk digest equals the whole-file digest")
    check("size", record.get("size"), Decimal(actual_size),
          "envelope declared size equals the actual byte length")
    check("role", record.get("role"), "SOURCE_FILE",
          "record is the source file itself, not an analysis material")
    check("contentType", record.get("contentType"), "text/csv",
          "declared media type is consistent with the declared CSV format")
    check("contentDelivery", record.get("contentDelivery"), "IMMUTABLE_INPUT_FILE_ONLY",
          "payload delivered as the immutable file; no base64 body to reconstruct")

    chunk_count = record.get("chunkCount")
    chunk_index = record.get("chunkIndex")
    if chunk_count != Decimal(1):
        raise BindingError(f"unexpected chunkCount {chunk_count!r}")
    if chunk_index != Decimal(0):
        raise BindingError(f"unexpected chunkIndex {chunk_index!r}")
    checks.append({
        "field": "chunkIndex coverage",
        "declaredInEnvelope": "chunkCount=1",
        "observedFromVerifiedBytes": "[0]",
        "match": True,
        "note": "indices 0..chunkCount-1 present exactly once; no gap or duplicate",
    })
    if "contentBase64" in record:
        raise BindingError(
            "contentBase64 unexpectedly present in the envelope record; delivery is "
            "IMMUTABLE_INPUT_FILE_ONLY and calculations must never use base64"
        )
    checks.append({
        "field": "contentBase64",
        "declaredInEnvelope": "absent",
        "observedFromVerifiedBytes": "absent",
        "match": True,
        "note": "no encoded payload delivered, so no chunk decode/concatenation path applies",
    })

    return {
        "datasetReference": row["datasetReference"],
        "logicalFields": sorted(row),
        "recordFieldNames": sorted(record),
        "recordDecimalTypedFields": sorted(
            name for name, val in record.items() if isinstance(val, Decimal)
        ),
        "checks": checks,
    }


def parse_original_csv(raw_bytes: bytes, csv_dialect: dict) -> dict:
    """Parse the verified original CSV bytes with the stdlib reader.

    Columns are addressed by exact header NAME only. Every token stays a string
    (no NA/sentinel coercion), so nothing is silently converted to a number or
    to zero. Declared missing/null tokens from the schema are detected and
    reported rather than substituted.
    """
    try:
        text = raw_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ParseError(f"authorized CSV is not valid UTF-8: {exc}") from exc

    if text.startswith("\ufeff"):
        raise ParseError("UTF-8 BOM present in the authorized CSV header row")

    reader = csv.reader(io.StringIO(text, newline=""))
    physical_rows = [row for row in reader]
    if not physical_rows:
        raise ParseError("authorized CSV contains no header row")

    header = physical_rows[0]
    if len(set(header)) != len(header):
        raise ParseError(f"duplicate header names in the authorized CSV: {header}")
    for position, name in enumerate(header):
        if not name.strip():
            raise ParseError(f"blank header name at position {position}")

    data_rows = physical_rows[1:]
    ragged = [
        {"rowNumber": number, "fieldCount": len(rec), "headerCount": len(header)}
        for number, rec in enumerate(data_rows, start=2)
        if len(rec) != len(header)
    ]
    if ragged:
        raise ParseError(f"ragged data rows relative to the header width: {ragged}")

    records = [dict(zip(header, rec)) for rec in data_rows]

    missing_token = csv_dialect.get("missingToken", "\\M")
    null_token = csv_dialect.get("nullToken", "\\N")
    sentinel_hits = []
    for number, rec in enumerate(records, start=2):
        for name, token in rec.items():
            if token in (missing_token, null_token):
                sentinel_hits.append(
                    {"rowNumber": number, "column": name, "token": token}
                )
    blank_cells = [
        {"rowNumber": number, "column": name}
        for number, rec in enumerate(records, start=2)
        for name, token in rec.items()
        if token == ""
    ]

    return {
        "text": text,
        "header": header,
        "headerRowNumber": 1,
        "dataRows": records,
        "physicalLineCount": text.count("\n") + (0 if text.endswith("\n") else 1),
        "endsWithNewline": text.endswith("\n"),
        "raggedRows": ragged,
        "sentinelCells": sentinel_hits,
        "blankCells": blank_cells,
        "missingToken": missing_token,
        "nullToken": null_token,
    }

