def parse_original_csv(raw_bytes: bytes, csv_dialect: dict) -> dict:
    """Parse the verified original CSV bytes with the standard library reader.

    Columns are addressed by exact header NAME only; no cell is selected by
    physical position. Tokens stay strings, so nothing is silently coerced to a
    number or to zero, and declared missing/null sentinels are detected and
    reported instead of substituted.
    """
    try:
        text = raw_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ParseError(f"authorized CSV is not valid UTF-8: {exc}") from exc

    if text.startswith("\ufeff"):
        raise ParseError("UTF-8 BOM present in the authorized CSV header row")

    reader = csv.reader(io.StringIO(text, newline=""))
    physical_rows = [row for row in reader]
    if not physical_rows:
        raise ParseError("authorized CSV contains no header row")

    header = physical_rows[0]
    if len(set(header)) != len(header):
        raise ParseError(f"duplicate header names in the authorized CSV: {header}")
    for position, name in enumerate(header):
        if not name.strip():
            raise ParseError(f"blank header name at position {position}")

    data_rows = physical_rows[1:]
    ragged = [
        {"rowNumber": number, "fieldCount": len(rec), "headerCount": len(header)}
        for number, rec in enumerate(data_rows, start=2)
        if len(rec) != len(header)
    ]
    if ragged:
        raise ParseError(f"ragged data rows relative to the header width: {ragged}")

    records = [dict(zip(header, rec)) for rec in data_rows]

    missing_token = csv_dialect.get("missingToken", "\\M")
    null_token = csv_dialect.get("nullToken", "\\N")
    sentinel_hits = [
        {"rowNumber": number, "column": name, "token": token}
        for number, rec in enumerate(records, start=2)
        for name, token in rec.items()
        if token in (missing_token, null_token)
    ]
    blank_cells = [
        {"rowNumber": number, "column": name}
        for number, rec in enumerate(records, start=2)
        for name, token in rec.items()
        if token == ""
    ]

    return {
        "text": text,
        "header": header,
        "headerRowNumber": 1,
        "dataRows": records,
        "physicalLineCount": text.count("\n") + (0 if text.endswith("\n") else 1),
        "endsWithNewline": text.endswith("\n"),
        "raggedRows": ragged,
        "sentinelCells": sentinel_hits,
        "blankCells": blank_cells,
        "missingToken": missing_token,
        "nullToken": null_token,
    }

    checks.append({
        "field": "contentBase64",
        "declaredInEnvelope": "absent",
        "observedFromVerifiedBytes": "absent",
        "match": True,
        "note": "no encoded payload delivered, so no chunk decode/concat path applies",
    })

    return {
        "datasetReference": row["datasetReference"],
        "logicalFields": sorted(row),
        "recordFieldNames": sorted(record),
        "recordDecimalTypedFields": sorted(
            name for name, val in record.items() if isinstance(val, Decimal)
        ),
        "checks": checks,
    }


